-- Leave exactly one main image per record.
UPDATE photos SET is_primary = 0 WHERE record_id IN (SELECT id FROM records WHERE ehive_record_id IS NOT NULL) AND deleted_at IS NULL AND id <> (SELECT p.id FROM photos p WHERE p.record_id = photos.record_id AND p.deleted_at IS NULL ORDER BY p.is_primary DESC, p.added_at, p.id LIMIT 1);
